```go
package telemetry

import (
	"encoding/json"
	"os"
	"runtime"
	"time"

	"github.com/denisbrodbeck/machineid"
)

// BuildSearchPerformedPayload constructs a cli_search_performed event payload.
// Exported for testing. Returns nil if the machine ID cannot be resolved.
// The raw query is never included — only QueryHash.
func BuildSearchPerformedPayload(event SearchPerformedEvent, version string) *EventPayload {
	machineID, err := machineid.ProtectedID("entire-cli")
	if err != nil {
		return nil
	}
	properties := map[string]any{
		"search_id":    event.SearchID,
		"query_hash":   event.QueryHash,
		"mode":         event.Mode,
		"total":        event.Total,
		"page":         event.Page,
		"limit":        event.Limit,
		"result_count": len(event.Impressions),
		"impressions":  event.Impressions,
		"cli_version":  version,
		"os":           runtime.GOOS,
		"arch":         runtime.GOARCH,
	}
	if event.SessionID != "" {
		properties["session_id"] = event.SessionID
	}
	if event.PrevSearchID != "" {
		properties["prev_search_id"] = event.PrevSearchID
		properties["prev_search_clicked"] = event.PrevSearchClicked
	}
	return &EventPayload{
		Event:      "cli_search_performed",
		DistinctID: machineID,
		Properties: properties,
		Timestamp:  time.Now(),
	}
}

// TrackSearchPerformed sends a cli_search_performed event via a detached
// subprocess. Best-effort; callers own the settings.Telemetry opt-in check.
func TrackSearchPerformed(event SearchPerformedEvent, version string) {
	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
		return
	}
	payload := BuildSearchPerformedPayload(event, version)
	if payload == nil {
		return
	}
	if payloadJSON, err := json.Marshal(payload); err == nil {
		spawnDetachedAnalytics(string(payloadJSON))
	}
}

// BuildSearchClickPayload constructs a cli_search_result_clicked event payload.
// Exported for testing. Returns nil if the machine ID cannot be resolved.
func BuildSearchClickPayload(event SearchClickEvent, version string) *EventPayload {
	machineID, err := machineid.ProtectedID("entire-cli")
	if err != nil {
		return nil
	}
	properties := map[string]any{
		"search_id":                event.SearchID,
		"query_hash":               event.QueryHash,
		"result_id":                event.ResultID,
		"rank":                     event.Rank,
		"score":                    event.Score,
		"match_type":               event.MatchType,
		"seconds_since_impression": event.SecondsSinceImpression,
		"click_seq":                event.ClickSeq,
		"cli_version":              version,
		"os":                       runtime.GOOS,
		"arch":                     runtime.GOARCH,
	}
	if event.SessionID != "" {
		properties["session_id"] = event.SessionID
	}
	return &EventPayload{
		Event:      "cli_search_result_clicked",
		DistinctID: machineID,
		Properties: properties,
		Timestamp:  time.Now(),
	}
}

// TrackSearchClick sends a cli_search_result_clicked event via a detached
// subprocess. Best-effort; callers own the settings.Telemetry opt-in check.
func TrackSearchClick(event SearchClickEvent, version string) {
	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
		return
	}
	payload := BuildSearchClickPayload(event, version)
	if payload == nil {
		return
	}
	if payloadJSON, err := json.Marshal(payload); err == nil {
		spawnDetachedAnalytics(string(payloadJSON))
	}
}
```

Note the missing-key test detail: `session_id` **is** set in the first test (SessionID "sess-1") so it appears in the required list; the omission test covers the empty case.

