package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
)

// Search click-tracking (ENT-1528): impressions served by `entire search` are
// persisted here so a later `entire checkpoint explain <id>` can be attributed
// as a "click" on a recently served result — no agent cooperation required.
const (
	searchImpressionsFileName = "search-impressions.json"
	// searchImpressionsTTL bounds how long after a search an explain still
	// counts as a click for it.
	searchImpressionsTTL = time.Hour
	// searchImpressionsMaxSearches caps the store so it never grows unbounded.
	// ponytail: linear scan over <=20 searches x page-size results; fine at
	// this size, switch to an id-keyed map if the cap ever grows.
	searchImpressionsMaxSearches = 20
	// clickMatchMinPrefixLen is the shortest user-typed target we'll treat as
	// a prefix of a served ULID (12 = full legacy id length, so anything
	// shorter is too ambiguous to attribute).
	clickMatchMinPrefixLen = 12
)

// hashSearchQuery returns a short, non-reversible fingerprint of the query for
// telemetry: SHA-256 of the lowercased, whitespace-collapsed query, truncated
// to 16 hex chars. Raw query text is never sent (privacy convention:
// operational metadata only).
func hashSearchQuery(query string) string {
	normalized := strings.ToLower(strings.Join(strings.Fields(query), " "))
	sum := sha256.Sum256([]byte(normalized))
	return hex.EncodeToString(sum[:8])
}

type storedImpression struct {
	telemetry.SearchImpression
	Clicks int `json:"clicks,omitempty"`
}

type impressionRecord struct {
	SearchID  string             `json:"search_id"`
	QueryHash string             `json:"query_hash"`
	SessionID string             `json:"session_id,omitempty"`
	Timestamp time.Time          `json:"timestamp"`
	Results   []storedImpression `json:"results"`
}

type impressionLog struct {
	Searches []impressionRecord `json:"searches"`
}

type searchClickMatch struct {
	SearchID               string
	QueryHash              string
	SessionID              string
	ResultID               string
	MatchType              string
	Rank                   int
	ClickSeq               int
	Score                  float64
	SecondsSinceImpression float64
}

// searchImpressionsPath returns the store location under the git common dir
// (shared across worktrees, never part of the working tree), alongside the
// existing trail-refresh-spawn marker in <common-dir>/entire/.
func searchImpressionsPath(ctx context.Context) (string, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(commonDir, "entire", searchImpressionsFileName), nil
}

// loadImpressionLog reads the store; a missing or corrupt file yields an empty
// log (the store is best-effort telemetry state, never worth failing over).
func loadImpressionLog(path string) impressionLog {
	var log impressionLog
	data, err := os.ReadFile(path)
	if err != nil {
		return log
	}
	_ = json.Unmarshal(data, &log)
	return log
}

func pruneImpressionLog(log *impressionLog, now time.Time) {
	kept := log.Searches[:0]
	for _, rec := range log.Searches {
		if now.Sub(rec.Timestamp) <= searchImpressionsTTL {
			kept = append(kept, rec)
		}
	}
	log.Searches = kept
}

func recordHasClicks(rec impressionRecord) bool {
	for _, imp := range rec.Results {
		if imp.Clicks > 0 {
			return true
		}
	}
	return false
}

func saveImpressionLog(path string, log impressionLog) error {
	data, err := json.Marshal(log)
	if err != nil {
		return err
	}
	return jsonutil.WriteFileAtomic(path, data, 0o600)
}

// recordImpressions appends one search's served results to the store and
// reports the previous in-TTL search (for reformulation chaining). The
// read-modify-write is serialized with a flock so concurrent agent sessions
// in the same repo don't lose each other's impressions.
func recordImpressions(path string, rec impressionRecord, now time.Time) (prevSearchID string, prevClicked bool, err error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", false, err
	}
	release, err := flock.Acquire(path + ".lock")
	if err != nil {
		return "", false, err
	}
	defer release()

	log := loadImpressionLog(path)
	pruneImpressionLog(&log, now)
	if n := len(log.Searches); n > 0 {
		prevSearchID = log.Searches[n-1].SearchID
		prevClicked = recordHasClicks(log.Searches[n-1])
	}
	log.Searches = append(log.Searches, rec)
	if len(log.Searches) > searchImpressionsMaxSearches {
		log.Searches = log.Searches[len(log.Searches)-searchImpressionsMaxSearches:]
	}
	return prevSearchID, prevClicked, saveImpressionLog(path, log)
}

// impressionMatches reports whether a served result id corresponds to the
// explain target: exact match on the resolved full id or the raw target, or
// the target is an unambiguous (>=12 char) prefix of the served id — search
// hints always carry full ids, but a human may retype a prefix.
func impressionMatches(resultID, target, resolvedID string) bool {
	if resultID == "" {
		return false
	}
	if resultID == resolvedID || resultID == target {
		return true
	}
	return len(target) >= clickMatchMinPrefixLen && strings.HasPrefix(resultID, target)
}

// matchAndMarkClick looks up the most recent in-TTL impression matching the
// explain target, increments its click count, and returns the click metadata.
// Returns (nil, nil) when there is nothing to attribute — including when the
// store file does not exist (telemetry disabled or no recent search).
func matchAndMarkClick(path, target, resolvedID string, now time.Time) (*searchClickMatch, error) {
	if _, err := os.Stat(path); err != nil {
		return nil, nil //nolint:nilerr // missing store = nothing to attribute
	}
	release, err := flock.Acquire(path + ".lock")
	if err != nil {
		return nil, err
	}
	defer release()

	log := loadImpressionLog(path)
	pruneImpressionLog(&log, now)
	for ri := len(log.Searches) - 1; ri >= 0; ri-- {
		rec := &log.Searches[ri]
		for ii := range rec.Results {
			imp := &rec.Results[ii]
			if !impressionMatches(imp.ResultID, target, resolvedID) {
				continue
			}
			imp.Clicks++
			match := &searchClickMatch{
				SearchID:               rec.SearchID,
				QueryHash:              rec.QueryHash,
				SessionID:              rec.SessionID,
				ResultID:               imp.ResultID,
				MatchType:              imp.MatchType,
				Rank:                   imp.Rank,
				ClickSeq:               imp.Clicks,
				Score:                  imp.Score,
				SecondsSinceImpression: now.Sub(rec.Timestamp).Seconds(),
			}
			return match, saveImpressionLog(path, log)
		}
	}
	return nil, nil
}
