```go
// newSearchID mints a client-side search identifier. The search server
// response carries no request id (and the CLI merges several cell responses
// into one page), so the id that ties impressions to clicks is minted here.
// Returns "" on entropy failure; callers treat that as "tracking off".
func newSearchID() string {
	u, err := ulid.New(ulid.Now(), rand.Reader)
	if err != nil {
		return ""
	}
	return u.String()
}

// impressionsForPage converts one served page into impression tuples with
// 1-based ranks absolute across pages (page 2 of limit 5 starts at rank 6).
func impressionsForPage(pageResults []search.Result, limit, page int) []telemetry.SearchImpression {
	imps := make([]telemetry.SearchImpression, 0, len(pageResults))
	for i := range pageResults {
		r := &pageResults[i]
		imps = append(imps, telemetry.SearchImpression{
			ResultID:  r.ResultID(),
			Rank:      (page-1)*limit + i + 1,
			Score:     r.Meta.Score,
			MatchType: r.Meta.MatchType,
		})
	}
	return imps
}

// explainHint returns the ready-made fetch command for a hit, or "" for hit
// types `explain` cannot resolve (repo, pr, session). Checkpoint hits from
// another repo get --repo (cross-repo explain, ENT-1523); commit hits resolve
// via the local Entire-Checkpoint trailer only, so they get a hint only in
// the current repo.
func explainHint(r *search.Result, hitRepo, currentRepo string) string {
	resultID := r.ResultID()
	if resultID == "" {
		return ""
	}
	switch r.Type {
	case search.TypeCheckpoint:
		if hitRepo != "" && !strings.EqualFold(hitRepo, currentRepo) {
			return "entire checkpoint explain " + resultID + " --repo " + hitRepo
		}
		return "entire checkpoint explain " + resultID
	case search.TypeCommit:
		if hitRepo == "" || strings.EqualFold(hitRepo, currentRepo) {
			return "entire checkpoint explain " + resultID
		}
	}
	return ""
}
