// (settings.Telemetry == true). Best-effort and silent on failure: search
// output has already been written, tracking must never break it. The session
// id is the most-recent-session heuristic — best-effort metadata, not the
// correlation key (that's search_id + result_id).
func trackSearchImpressions(ctx context.Context, searchID, query, mode string, total, page, limit int, impressions []telemetry.SearchImpression) {
	if searchID == "" || len(impressions) == 0 {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil || s.Telemetry == nil || !*s.Telemetry {
		return
