	rec := impressionRecord{
		SearchID:  searchID,
		QueryHash: hashSearchQuery(query),
		SessionID: strategy.FindMostRecentSessionInCurrentWorktree(ctx),
		Timestamp: now,
	}
	rec.Results = make([]storedImpression, 0, len(impressions))
	for _, imp := range impressions {
		rec.Results = append(rec.Results, storedImpression{SearchImpression: imp})
	}
	prevSearchID, prevClicked, err := recordImpressions(path, rec, now)
	if err != nil {
		return
	}
	telemetry.TrackSearchPerformed(telemetry.SearchPerformedEvent{
		SearchID:          searchID,
		QueryHash:         rec.QueryHash,
		SessionID:         rec.SessionID,
		Mode:              mode,
		Total:             total,
		Page:              page,
		Limit:             limit,
		Impressions:       impressions,
		PrevSearchID:      prevSearchID,
		PrevSearchClicked: prevClicked,
	}, versioninfo.Version)
}
