// maybeTrackSearchClick attributes a successful explain resolution to a
// recently served search impression — the "click" in the agent search funnel
// (ENT-1528). Zero agent cooperation: correlation is purely (target,
// resolved id) against the local impression store. Best-effort and silent;
// explain output must never be affected.
//
// Known limitation: the prose commit-SHA fallback re-enters resolution with
// the trailer-derived checkpoint id, so a click on a commit search hit only
// attributes when that id itself was an impression.
func maybeTrackSearchClick(ctx context.Context, target, resolvedID string) {
	path, err := searchImpressionsPath(ctx)
	if err != nil {
