		cmd = "entire checkpoint explain " + resultID
		if hitRepo != "" && !strings.EqualFold(hitRepo, currentRepo) {
			cmd += " --repo " + hitRepo
		}
	case search.TypeCommit:
		if hitRepo != "" && !strings.EqualFold(hitRepo, currentRepo) {
			return ""
		}
		cmd = "entire checkpoint explain " + resultID
	default:
		return ""
	}
	if searchID != "" {
		cmd += " --search-id " + searchID + ":" + strconv.Itoa(rank)
	}
	return cmd
